SELECT * FROM customer LIMIT 20
-- Q1. What is the total revenue generated by male vs. female customers?
SELECT gender,SUM(Purchase_amount) FROM customer
GROUP BY gender

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount FROM customer
WHERE discount_applied='Yes' AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer)

-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased, AVG(review_rating) AS avg_rating FROM customer
GROUP BY item_purchased
ORDER BY avg_rating DESC
LIMIT 5

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping
SELECT shipping_type, AVG(purchase_amount) AS avg_amount FROM customer
WHERE shipping_type LIKE '%Express%' OR shipping_type LIKE '%Standard%'
GROUP BY shipping_type

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
SELECT subscription_status, COUNT(customer_id) AS total_customers, AVG(purchase_amount) AS avg_spend, SUM(purchase_amount) AS total_amount FROM customer
GROUP BY subscription_status
ORDER BY total_amount DESC

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased, COUNT(*) AS total_count,
COUNT(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE NULL END) AS discount_applied_count,
ROUND((COUNT(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE NULL END)*100/COUNT(*)),2) AS percentages FROM customer
GROUP BY item_purchased
ORDER BY percentages DESC LIMIT 5

-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases,
-- and show the count of each segment.
SELECT COUNT(customer_id) AS Customers_count,
CASE WHEN previous_purchases = 1 THEN 'New'
     WHEN previous_purchases <= 10 THEN 'Returning'
	 WHEN previous_purchases >10 THEN 'Loyal'
	 END AS customer_type
FROM customer
GROUP BY customer_type

