-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?|
SELECT previous_purchases, subscription_status, COUNT(customer_id),
CASE WHEN previous_purchases > 5 AND subscription_status = 'Yes' THEN 'Repeat buyers'
     ELSE 'No' END AS are_they_repeated
FROM customer
GROUP BY previous_purchases, subscription_status

--For count we can
SELECT Subscription_status, COUNT(customer_id) AS repeat_buyers FROM customer
WHERE customer.previous_purchases > 5
GROUP BY subscription_status

-- Q10. What is the revenue contribution of each age group?
SELECT SUM(purchase_amount) AS revenue_contribution, age_group FROM customer
GROUP BY age_group
ORDER BY revenue_contribution DESC